var shrinkPicture = (src, size) => new Promise((resolve, reject) => {
  const image = new Image();
  image.onload = () => {
    const scale = Math.min(1, size / Math.max(image.naturalWidth || 1, image.naturalHeight || 1));
    const canvas2 = document.createElement("canvas");
    canvas2.width = Math.max(1, Math.round(image.naturalWidth * scale));
    canvas2.height = Math.max(1, Math.round(image.naturalHeight * scale));
    const context2d = canvas2.getContext("2d");
    if (!context2d) return reject(new Error("no canvas"));
    context2d.drawImage(image, 0, 0, canvas2.width, canvas2.height);
    resolve(canvas2.toDataURL("image/jpeg", 0.82));
  };
  image.onerror = () => reject(new Error("unreadable picture"));
  image.src = src;
});
