// desktop/film-suite/src/music/pro/mpro-css.js
var MPRO_CSS = `
.mpro{--mp-ph:var(--ui-text-primary,#f4f1ea);--mp-sec:var(--ui-purple,#9e94d5);--mp-grid:var(--ui-cyan,#6f9ba6);--mp-ink:#101214;--mp-head:96px;--mp-ab-h:28px;--mp-rows-h:216px;--mp-barline:color-mix(in srgb,var(--ui-text-secondary) 42%,var(--fw-row-sel));display:flex;flex-direction:column;gap:10px;min-width:0;font-size:var(--fw-fs,.75rem);line-height:1.4;color:var(--ui-text-secondary)}
.mpro *{box-sizing:border-box}
.mpro .fim-btn{align-self:auto}
.mpro-grow{flex:1 1 auto}
.mpro-note{margin:0;color:var(--ui-text-secondary);font-size:var(--fw-fs,.75rem)}
.mpro-progress{position:absolute;left:0;top:0;height:2px;background:var(--ui-accent);z-index:6;pointer-events:none;transition:width .3s linear}
.mpro-ab-in{display:flex;flex-direction:column;gap:8px;padding:10px 12px;border:1px solid var(--fw-line);border-radius:var(--fw-r2);background:var(--ui-bg-elevated,var(--ui-bg-chrome))}
.mpro-ab-title{margin:0;font-size:var(--fw-fs,.75rem);font-weight:600;color:var(--ui-text-primary)}
.mpro-ab-row{display:flex;align-items:center;gap:8px}
.mpro-ab-run{flex:1 1 auto;color:var(--ui-text-primary);font-variant-numeric:tabular-nums}
.mpro-ab .fw-select{width:100%;height:var(--fw-ctl-h,1.75rem);min-height:var(--mp-ab-h)}
.mpro-ab-go{justify-content:center}
.mpro-an{display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:4px 0 8px;border-bottom:1px solid var(--fw-line)}
.mpro-an>.fw-select{flex:1 1 120px;min-width:0;height:var(--fw-ctl-h,1.75rem)}
.mpro-an-v{flex:1 1 auto;min-width:0;color:var(--ui-text-primary)}
.mpro-an>.fw-btn{height:var(--fw-ctl-h,1.75rem)}
.mpro-bar,.mpro-transport{display:flex;flex-wrap:wrap;align-items:center;gap:8px 10px}
.mpro-facts{display:inline-flex;flex-wrap:wrap;align-items:center;gap:2px 14px;color:var(--ui-text-primary);font-variant-numeric:tabular-nums}
.mpro-zoom{display:inline-flex;align-items:center;gap:8px;color:var(--ui-text-secondary)}
.mpro-zoom input{width:120px;accent-color:var(--ui-accent)}
.mpro-btn{gap:6px}
/* w12-look2: the strip toggles are ghosts, so the pressed Snap (--fw-press) is the only filled one (bench: the off "Fit selection" kept the .fim-btn fill and looked more pressed than Snap). */
.mpro .mpro-btn:not([aria-pressed=true]){background:transparent}
.mpro-check{display:inline-flex;align-items:center;gap:6px;color:var(--ui-text-secondary);font-size:var(--fw-fs,.75rem);white-space:nowrap;cursor:pointer}
.mpro-check input{width:14px;height:14px;margin:0;accent-color:#2c5fe6}
.mpro-check:has(input:disabled){opacity:.5;cursor:default}
.mpro-btn[aria-pressed=true],.mpro-btn[aria-pressed=true]:hover:not(:disabled){background:var(--fw-press);border-color:transparent;box-shadow:none;color:var(--ui-text-primary)}
.mpro-btn svg{flex:0 0 auto}
.mpro-play{min-width:84px;justify-content:center}
/* w7-spur: the head column sits left of the timeline (outside it), so every track's data starts at the ruler's 0. */
.mpro-tl{position:relative;margin-left:var(--mp-head);border:1px solid color-mix(in srgb,var(--ui-base) 10%,transparent);border-radius:0 4px 4px 0;background:var(--ui-bg-editor,var(--ui-bg-chrome));user-select:none;touch-action:none;overflow:visible}
.mpro-ruler{position:relative;height:46px;border-bottom:1px solid var(--fw-line);cursor:pointer;overflow:hidden;border-radius:0 6px 0 0;outline-offset:-2px}
.mpro-tick{position:absolute;top:0;width:1px;height:8px;background:var(--ui-text-secondary);pointer-events:none}
.mpro-rl,.mpro-bl{position:absolute;white-space:nowrap;overflow:hidden;font-variant-numeric:tabular-nums;pointer-events:none;font-size:var(--fw-fs,.75rem);line-height:16px}
.mpro-rl{top:4px;color:var(--ui-text-secondary)}
.mpro-bl{top:21px;color:var(--ui-text-secondary)}
.mpro-lane{position:relative;height:26px;border-bottom:1px solid var(--fw-line);overflow:hidden;background:var(--ui-bg-editor,var(--ui-bg-chrome))}
.mpro-lane-empty{position:absolute;left:8px;top:3px;color:var(--ui-text-secondary);font-size:var(--fw-fs,.75rem)}
.mpro-sec{position:absolute;top:0;bottom:0;display:flex;align-items:center;min-width:2px;padding:0 6px;border:0;border-left:2px solid var(--mp-sec);background:color-mix(in srgb,var(--mp-sec) 22%,transparent);color:var(--ui-text-primary);font:inherit;font-size:var(--fw-fs,.75rem);text-align:left;cursor:pointer;overflow:hidden;white-space:nowrap}
.mpro-sec.is-odd{background:color-mix(in srgb,var(--mp-sec) 36%,transparent)}
.mpro-sec span{overflow:hidden;text-overflow:ellipsis}
.mpro-sec:hover{background:color-mix(in srgb,var(--mp-sec) 48%,transparent)}
.mpro-sec:focus-visible,.mpro-ev-main:focus-visible,.mpro-ruler:focus-visible,.mpro-ov:focus-visible,.mpro-in:focus-visible{outline:2px solid var(--ui-accent);outline-offset:1px}
.mpro-wave{position:relative;height:140px;cursor:crosshair;overflow:hidden}
.mpro-canvas{position:absolute;inset:0;display:block;color:var(--ui-text-secondary);pointer-events:none}
/* fs-inout: IN-OUT is the shared sign (src/shared/inout, E17) over ruler, lanes and waveform; outside it the chrome colour at half
   strength (z 3, above the beat marks); the labels and section names sit above it (z 4) so they keep their contrast. */
.mpro-tl>.io,.mpro-tl>.io .io-dim{z-index:3}
.mpro-rl,.mpro-bl,.mpro-sec>span,.mpro-barn{z-index:4}
.mpro-sec>span{position:relative}
.mpro-stage{position:relative}
.mpro-marks{position:absolute;inset:0;pointer-events:none;z-index:2}
.mpro-mk{position:absolute;display:block;width:1px}
.mpro-mk.is-beat{bottom:0;height:9px;background:var(--ui-text-secondary)}
/* L5-04: beats too close for ticks stay visible as a 1 px dotted row; closer still, a chip says so. */
.mpro-beatrow{position:absolute;left:0;right:0;bottom:2px;top:calc(100% - 6px)}
.mpro-bdot{position:absolute;bottom:0;top:0;width:1px;background:var(--ui-text-primary)}
.mpro-beatchip{position:absolute;right:6px;bottom:6px;z-index:5;padding:2px 6px;border:1px solid var(--fw-line-strong);border-radius:var(--fw-r1,3px);background:var(--fw-row-sel);color:var(--ui-text-primary);font-size:var(--fw-fs,.75rem);pointer-events:none;white-space:nowrap}
.mpro-nobars{right:6px;left:auto!important;color:var(--ui-text-secondary)}
/* w32-fix5 AUD-151: in the empty Bars lane the note sits like a bar number (3 px down, 16 px line), from the lane's left. */
.mpro-barsl .mpro-nobars{position:absolute;top:3px;left:8px!important;right:auto;white-space:nowrap;font-size:var(--fw-fs,.75rem);line-height:var(--fw-lh,1rem);pointer-events:auto;z-index:4}
.mpro-mk.is-down{top:0;bottom:0;background:var(--mp-grid);opacity:.6}
.mpro-mk.is-down::after{content:'';position:absolute;left:-1px;bottom:0;width:3px;height:18px;background:var(--mp-grid);opacity:1}
.mpro-mk.is-down.is-unsure{background:none;border-left:1px dashed var(--mp-grid);opacity:.75}
.mpro-ph{position:absolute;top:38px;bottom:0;width:2px;margin-left:-1px;background:var(--mp-ph);pointer-events:none;z-index:10;box-shadow:0 0 0 1px rgba(0,0,0,.35)}
.mpro-ph-head{position:absolute;top:38px;margin-left:-7px;width:0;height:0;pointer-events:none;border-left:7px solid transparent;border-right:7px solid transparent;border-top:8px solid var(--mp-ph);filter:drop-shadow(0 0 1px rgba(0,0,0,.5))}
.mpro-transport{padding:2px 0}
.mpro-timecode{display:inline-flex;align-items:baseline;font-variant-numeric:tabular-nums;color:var(--ui-text-primary);min-width:170px}
.mpro-timecode b{font-weight:600}
.mpro-sep,.mpro-timecode [data-testid=mpro-total]{color:var(--ui-text-secondary)}
.mpro-range{display:inline-flex;flex-wrap:nowrap;align-items:center;gap:8px 10px}
.mpro-field{display:inline-flex;align-items:center;gap:6px;color:var(--ui-text-secondary)}
.mpro-in{width:88px;height:28px;padding:0 8px;border:1px solid var(--fim-edge);border-radius:3px;background:var(--fw-track);color:var(--ui-text-primary);font:inherit;font-size:var(--fw-fs,.75rem);font-variant-numeric:tabular-nums}
.mpro-field:last-of-type .mpro-in{width:76px}
.mpro-unit{color:var(--ui-text-secondary)}
.mpro-derived{display:inline-flex;flex-wrap:wrap;gap:2px 12px;color:var(--ui-text-secondary);font-variant-numeric:tabular-nums}
.mpro-events{display:flex;flex-direction:column;gap:6px;border-top:1px solid var(--fw-line);padding-top:10px}
.mpro-ev-head{display:flex;flex-wrap:wrap;align-items:center;gap:6px 12px}
.mpro-events .fim-label{font-size:var(--fw-fs,.75rem);letter-spacing:.06em}
.fim.fmu .fim-label{color:var(--ui-text-secondary)}
.mpro-counts{color:var(--ui-text-secondary);font-variant-numeric:tabular-nums}
.mpro-ev-wrap{position:relative}
.mpro-ev-list{display:flex;flex-direction:column;max-height:232px;overflow-y:auto;overscroll-behavior:contain;border:1px solid var(--fw-line);border-radius:2px}
.mpro-more{position:absolute;left:1px;right:1px;bottom:1px;height:28px;display:flex;align-items:flex-end;justify-content:center;padding-bottom:3px;pointer-events:none;border-radius:0 0 2px 2px;background:linear-gradient(to bottom,transparent,var(--fw-track) 80%);color:var(--ui-text-primary);font-size:var(--fw-fs,.75rem);font-weight:600}
.mpro-ev{flex:0 0 auto;display:flex;align-items:center;min-height:32px;border-bottom:1px solid var(--fw-line)}
.mpro-ev:last-child{border-bottom:0}
.mpro-ev.is-active{background:var(--fw-row-sel)}
/* p0-fix item 3 (artist 26.10. A2): the current event = the neutral row fill, no accent tint, no accent bar, no rounded clip */
.mpro-ev.is-current{background:var(--fw-row-sel);box-shadow:none}
.mpro-ev-main:hover{background:var(--fw-hover,var(--fw-row-sel))}
.mpro-tag{flex:0 0 auto;padding:0 8px;border-radius:2px;background:color-mix(in srgb,var(--mp-sec) 30%,transparent);border:1px solid var(--mp-sec);color:var(--ui-text-primary);font-size:var(--fw-fs,.75rem);line-height:18px;white-space:nowrap}
.mpro-note.is-warn{color:var(--ui-text-primary);text-decoration:underline dotted;text-underline-offset:3px;cursor:help}
.mpro-ev-main{flex:1 1 auto;justify-content:flex-start;min-width:0;display:flex;align-items:center;gap:12px;height:32px;padding:0 10px;border:0;background:transparent;color:var(--ui-text-primary);font:inherit;font-size:var(--fw-fs,.75rem);text-align:left;cursor:pointer}
.mpro-dot{flex:0 0 auto;width:8px;height:8px;border-radius:50%;background:var(--ui-text-secondary)}
.mpro-ev.is-section .mpro-dot{background:var(--mp-sec)}
.mpro-ev.is-downbeat .mpro-dot{background:var(--mp-grid)}
.mpro-ev-label{flex:0 1 auto;min-width:64px;max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mpro-ev-time{flex:0 0 auto;font-variant-numeric:tabular-nums;color:var(--ui-text-secondary)}
.mpro-ev-time.is-shot{color:var(--ui-text-secondary);text-align:left}
.mpro-ev-actions{flex:0 0 auto;display:inline-flex;align-items:center;gap:6px;padding-right:8px}
.mpro-ov{position:relative;height:44px;border:1px solid var(--fw-line);border-radius:6px;background:var(--fw-track);cursor:pointer;overflow:hidden;touch-action:none;user-select:none}
.mpro-ov .mpro-canvas{color:var(--ui-text-tertiary)}
.mpro-ov-dim{position:absolute;top:0;bottom:0;background:color-mix(in srgb,var(--ui-bg-chrome) 60%,transparent);pointer-events:none}
.mpro-ov-win{position:absolute;top:0;bottom:0;border:2px solid var(--ui-accent);background:color-mix(in srgb,var(--ui-accent) 14%,transparent);border-radius:3px;pointer-events:none}
.mpro-ov-ph{position:absolute;top:0;bottom:0;width:2px;margin-left:-1px;background:var(--mp-ph,#f4f1ea);pointer-events:none}
@container fim (max-width: 640px){.mpro{--mp-head:28px;--mp-rows-h:144px}}
/* w16-tv item 2 (D-2 Tafel 2a; DESIGN.md Time view): the Audio page's lanes. Head column 104 at every width (was 88) (name 12/600
   --fw-t2, 8 px in); overview 24 over the lane column only, its view window a neutral outline; ruler 28 in m:ss;
   event lanes 22, curves 32; the lane list scrolls with a visible scrollbar (AUD-063). */
.mpro.is-audio{--mp-head:104px} /* orchestrator item (w39-p2-wins): 104, was 88: a stem head holds its full name (Drums 36 px at 12/600) plus 4 px air beside the 24 px M / S pair */
.mpro.is-audio .mpro-hd{justify-content:flex-start;padding:0 0 0 8px;font-size:var(--fw-fs,.75rem);font-weight:600;color:var(--fw-t2,var(--ui-text-secondary))}
.mpro.is-audio .mpro-hd-name{flex:1 1 auto;text-align:left}
.mpro.is-audio .mpro-hd-name>.mpro-hd-full{display:inline}
.mpro.is-audio .mpro-hd-name::before{content:none}
.mpro.is-audio .mpro-trk.is-ruler>.mpro-hd{align-items:center;padding-top:0}
.mpro.is-audio .mpro-ov{box-sizing:border-box;height:var(--fw-ctl-h-sm,1.5rem);margin-left:calc(var(--mp-head) + 1px);margin-right:1px;border:0;border-radius:0}
.mpro.is-audio .mpro-ov-win{border:1px solid var(--fw-t2,var(--ui-text-secondary));background:transparent;border-radius:0}
.mpro.is-audio .mpro-ruler{height:var(--fw-ctl-h,1.75rem);border-radius:0}
.mpro.is-audio .mpro-rl{top:3px}
.mpro.is-audio .mpro-tick{top:auto;bottom:0;height:.5rem}
.mpro.is-audio .mpro-tick.is-minor{height:.25rem;opacity:.7}
.mpro.is-audio .mpro-ph,.mpro.is-audio .mpro-ph-head{top:20px}
.mpro.is-audio .mpro-lane,.mpro.is-audio .mpro-mrow{height:1.375rem}
.mpro.is-audio .mpro-energy{height:2rem}
/* AUD-064: on the waveform the bar lines are the quiet track bar line (never the cyan full-height rule over the envelope);
   the bar stubs at its foot go, the Bars lane carries the numbers. */
.mpro.is-audio .mpro-mk.is-down{background:var(--mp-barline);opacity:1}
.mpro.is-audio .mpro-mk.is-down::after{content:none}
/* w20-song AUD-132 (Tafel 2a: one thin neutral grid, no dashed lines): an unsure bar line on Audio Edit is solid and fainter; the word "unsure" stays in its title and the Tempo head. */
.mpro.is-audio .mpro-mk.is-down.is-unsure{border-left:0;background:var(--mp-barline);opacity:.45}
/* The grid runs behind the envelope (Logic, Resolve): the waveform is drawn over its bar lines. */
.mpro.is-audio .mpro-marks{z-index:0}
.mpro.is-audio .mpro-canvas{z-index:1}
.mpro-barsl{overflow:hidden}
/* w18-aedit items 1-3 (board 2a; kit .d2-gl/.d2-sec/.d2-num; Ableton/Logic: one neutral grid behind the content): ONE recessive
   grid, 1 px --fw-line-2 for bars and --fw-line for beats, drawn only in Sections and Waveform; the Bars lane carries a
   tick only where its number stands; the parts are plain names on the lane ground (base 8 %, DESIGN.md section fill) with a
   1 px boundary, no colour. */
.mpro.is-audio{--mp-barline:var(--fw-line-2,color-mix(in srgb,var(--ui-text-secondary) 30%,transparent))}
.mpro.is-audio .mpro-mk.is-beat{top:0;bottom:0;height:auto;background:var(--fw-line,color-mix(in srgb,var(--ui-text-secondary) 16%,transparent))}
.mpro.is-audio .mpro-sec,.mpro.is-audio .mpro-sec.is-odd{padding:0 6px;border-left:1px solid var(--fw-line-2,var(--fw-line));background:color-mix(in srgb,var(--ui-base,#888) 8%,transparent);color:var(--fw-t1,var(--ui-text-primary))}
.mpro.is-audio .mpro-sec:hover{background:color-mix(in srgb,var(--ui-base,#888) 14%,transparent)}
.mpro.is-audio .mpro-barn{color:var(--fw-t2,var(--ui-text-secondary))}
/* w18-aedit item 1 (owner audit 8; Logic: Bar 1 lives on the bar ruler): the Bar 1 handle in the Bars lane, a 2 px grab line
   at bar 1 over the lane's height; the lane's own "1" names it (the flag word stays for screen readers). */
.mpro.is-audio .mpro-wave .mpro-canvas{color:color-mix(in srgb,var(--mp-grid) 70%,var(--ui-text-primary))} /* w18-aedit: board 2a kit .d2-mask, DESIGN.md Time view colour: sound --ui-cyan */
.mpro-barsl .mpro-b1{top:0;bottom:0;height:auto;width:12px;margin-left:-6px}
.mpro-barsl .mpro-b1::before{left:5px;top:0;bottom:0;height:auto;width:2px;background:var(--fw-t1,var(--ui-text-primary))}
.mpro-barsl .mpro-b1-flag{position:absolute;min-width:0;padding:0;border:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
/* w16-tv item 3: the transport is the Cut's .tlt row (36 px) under the lanes; the fields are framed values (.fw-num). */
/* Flex, not the Cut's 1fr grid: equal halves centre the icons while the fields fit; when they do not, the fields keep
   their width and the icons move left (never under a field). */
.mpro.is-audio .atl{display:flex;align-items:center;gap:12px;padding:0 8px;background:var(--fw-s1,var(--ui-bg-chrome));border-top:1px solid var(--fw-line);border-bottom:1px solid var(--fw-line)}
.mpro.is-audio .atl .tlt-btns .fw-btn{width:var(--fw-ctl-h,1.75rem);height:var(--fw-ctl-h,1.75rem)}
.mpro.is-audio .atl .mpro-timecode{min-width:0}
.fim.fmu .mpro.is-audio .atl .mpro-timecode>b{font-size:var(--fw-fs-title,.875rem)!important;font-weight:600;font-variant-numeric:tabular-nums;color:var(--fw-t1,var(--ui-text-primary))}
.mpro.is-audio .atl .tlt-end{gap:12px}
.mpro.is-audio .atl .mpro-field{gap:4px;color:var(--fw-t3,var(--ui-text-secondary))}
.mpro.is-audio .atl .fw-num{width:auto;flex:none;display:inline-flex;align-items:center;height:var(--fw-ctl-h-sm,1.5rem);border:1px solid var(--fw-line-strong,var(--fw-line-2));border-radius:var(--fw-r1,3px);background:var(--fw-s0,var(--fw-track))}
.fim.fmu .mpro.is-audio .atl input.mpro-in{box-sizing:border-box;width:4.75rem;min-width:0;height:100%;padding:0 6px;border:0;background:transparent;font-variant-numeric:tabular-nums}
.mpro.is-audio .atl .tlt-tc{flex:1 1 0;min-width:max-content}
.mpro.is-audio .atl .tlt-btns{flex:none}
.mpro.is-audio .atl .tlt-end{flex:1 1 0;min-width:max-content;justify-content:flex-end;overflow:visible}
.mpro.is-audio .atl .mpro-field{flex:none}
/* Below 900 px all three fields stay (nothing dropped); their words become the fields' tooltips and the bar count goes. */
@container fim (max-width: 899px){.mpro.is-audio .atl{gap:6px}.mpro.is-audio .atl .tlt-end{gap:4px}.mpro.is-audio .atl .mpro-field>span:first-child{position:absolute;overflow:hidden;clip-path:inset(50%);white-space:nowrap}.fim.fmu .mpro.is-audio .atl input.mpro-in{width:4.25rem;padding:0 4px}.mpro.is-audio .atl .mpro-derived{display:none}}
.mpro-barn{position:absolute;top:3px;color:var(--ui-text-primary);font-size:var(--fw-fs,.75rem);line-height:var(--fw-lh,1rem);font-variant-numeric:tabular-nums;pointer-events:none;z-index:4}
.mpro.is-audio .smap-rows{scrollbar-width:thin;scrollbar-color:var(--fw-line-strong,var(--fw-line-2)) transparent}
.mpro.is-audio .smap-rows::-webkit-scrollbar{display:block;width:8px}
/* w17-aedit item 2 (AUD-074; DESIGN.md Time view, the Cut .tlv: viewer and timeline fill, transport fixed): on Audio Edit the
   lane area takes the height between the tool row/overview and the transport; the lane list scrolls only when its lanes
   exceed it (the fixed --mp-rows-h goes for Audio Edit; Create keeps its layout). The transport sits flush under the
   lanes at the bottom of the work column. Below 900 px the module scrolls and the lanes keep their own height. */
.mpro.is-audio .mpro-tlrow+.atl{margin-top:calc(-1 * var(--mp-col-gap,10px))}
@container fim (min-width: 900px){
.fmu-main:has(>.fmu-tl .mpro.is-audio){display:flex;flex-direction:column}
.fmu-main>.fmu-tl:has(.mpro.is-audio){flex:1 1 auto;min-height:0;width:100%}
.fmu-tl>.mpro-root:has(>.mpro.is-audio){flex:1 1 auto;min-height:0}
.mpro.is-audio{flex:1 1 auto;min-height:0}
.mpro.is-audio>.mpro-col{flex:1 1 auto;min-height:0;overflow-y:hidden}
.mpro.is-audio>.mpro-col>.mpro-tlrow{flex:1 1 auto;min-height:0;display:flex;flex-direction:column}
.mpro.is-audio .mpro-tl{flex:1 1 auto;min-height:0;display:flex;flex-direction:column}
.mpro.is-audio .mpro-tl>*{flex:none}
.mpro.is-audio .mpro-tl>.smap{flex:1 1 0;min-height:0;display:flex;flex-direction:column}
.mpro.is-audio .mpro-tl .smap-rows{flex:1 1 auto;min-height:0;max-height:none}
/* The room under the last lane reads as the track area (Logic/Resolve): the head column and its rule run on to the
   transport, the lane side keeps the lanes' ground; never a blank band. */
.mpro.is-audio .mpro-tl .smap-rows{background:linear-gradient(to right,var(--fw-row-sel) 0 calc(var(--mp-head) - 1px),var(--fw-line-2) calc(var(--mp-head) - 1px) var(--mp-head),var(--ui-bg-editor,var(--ui-bg-chrome)) var(--mp-head))}
}
/* w17-aedit item 3 (AUD-076): the bar facts keep the space before the first dot (a flex item trims its leading space),
   so "song.mp3 · 4:24 · ..." has the same separator spacing as everywhere. */
.aud-file>.aud-file-f{white-space:pre}
/* w17-aedit item 3 (AUD-075): a transport value never runs out of its column. The transport is its own container; when
   it is too narrow for the bar count, the count goes (it stays in the Length field's tooltip). */
.mpro.is-audio .atl{container:atl / inline-size;min-width:0}
@container atl (max-width: 720px){.mpro.is-audio .atl .mpro-derived{display:none}}
@container atl (max-width: 600px){.mpro.is-audio .atl .tlt-end{gap:4px}.mpro.is-audio .atl .mpro-field>span:first-child{position:absolute;overflow:hidden;clip-path:inset(50%);white-space:nowrap}}
@media (max-width:640px){.mpro-timecode{min-width:0}.mpro-ev-time.is-shot{min-width:0}.mpro-zoom input{width:80px}}
`;

