var MUSIC_CREATE_CSS = `
.mus-create{display:contents}
.mus-sheet{--mus-head:88px;--mus-ruler:28px;--mus-curve:32px;--mus-event:22px;--mus-take:52px;position:relative;min-width:0}
.mus-ruler,.mus-row{display:grid;grid-template-columns:var(--mus-head) minmax(0,1fr);min-width:0}
.mus-ruler{position:sticky;top:0;z-index:2;height:var(--mus-ruler);background:var(--fw-s1);border-bottom:1px solid var(--fw-line)}
.mus-ticks{position:relative;min-width:0;overflow:hidden}
.mus-tick{position:absolute;top:0;bottom:0;border-left:1px solid var(--fw-line);padding-left:4px;color:var(--fw-t3);font-size:var(--fw-fs-meta,.6875rem);display:flex;align-items:flex-end;padding-bottom:4px;white-space:nowrap}
.mus-row{height:var(--mus-take);border-bottom:1px solid var(--fw-line);cursor:pointer;position:relative}
.mus-row.is-notes{height:var(--mus-curve);cursor:default}
.mus-row.is-event{height:var(--mus-event);cursor:default}
.mus-bar{position:absolute;top:0;bottom:0;border-left:1px solid var(--fw-line-2);padding-left:3px;display:flex;align-items:center;color:var(--fw-t3);white-space:nowrap}
.mus-secb{position:absolute;top:3px;bottom:3px;box-sizing:border-box;border-left:1px solid var(--fw-line-2);background:color-mix(in srgb,var(--ui-base,var(--fw-t1)) 8%,transparent);padding-left:6px;display:flex;align-items:center;color:var(--fw-t2);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mus-lock{display:flex;align-items:center;gap:6px;flex:1 1 auto;min-width:0;white-space:nowrap}
.mus-lock-t{min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.mus-lock svg{width:var(--fw-fs,.75rem);height:var(--fw-fs,.75rem);color:var(--fw-t3)}
.mus-sec-b>.mus-edit{justify-self:start}
.mus-create .fw-num.mus-num,.mus-create .fw-prow .fw-pctl>.fw-num.mus-num{width:100%;min-width:0;flex:1 1 auto;margin-left:0}
.mus-create .fw-num.mus-num>input,.mus-create .fw-prow .fw-pctl>.fw-num.mus-num>input{flex:1 1 auto;min-width:0;width:auto;height:auto;border:0;background:transparent;box-shadow:none;text-align:right;padding:0 4px 0 8px}
.mus-create .fw-num.mus-num>input::placeholder{color:var(--fw-t3);text-align:left}
.mus-create .fw-num.mus-num>.fw-num-u{flex:none;display:flex;align-items:center;padding-right:6px;background:transparent;color:var(--fw-t3)}
.mus-sec-b .fw-pctl>.fw-select{flex:1 1 auto;min-width:0}
.mus-sec-b>[data-missing=true]>label,.mus-sec-b[data-missing=true] .mus-prow>label{color:var(--fw-warn)}
.mus-create [aria-invalid=true].aud-ta{border-color:var(--fw-warn);box-shadow:inset 2px 0 0 var(--fw-warn)}
.mus-row.is-selected{background:var(--fw-row-sel)}
.mus-row:focus-visible{outline:2px solid var(--fw-accent);outline-offset:-2px}
.mus-head{display:flex;flex-direction:column;justify-content:center;gap:2px;padding-left:8px;min-width:0;overflow:hidden;white-space:nowrap}
.mus-head b{font-weight:600;color:var(--fw-t2)}
.mus-head span{color:var(--fw-t3);font-size:var(--fw-fs-meta,.6875rem)}
.mus-row.is-failed .mus-head span{color:var(--fw-err)}
.mus-lane{position:relative;min-width:0;overflow:hidden;color:${TL_TOKENS.wave}}
.mus-row:hover:not(.is-selected){background:var(--fw-hover)}
.mus-head{position:sticky;left:0;z-index:1;background:inherit}
.mus-row.is-notes-take .mus-note{background:var(--fw-t2)}
.mus-lane .fsp-snd-wave{position:absolute;inset:18px 0 4px 0;color:inherit;background:transparent}
.mus-cap{position:absolute;left:4px;top:1px;line-height:var(--fw-lh,1rem);color:var(--fw-t3);font-size:var(--fw-fs-meta,.6875rem);white-space:nowrap}
.mus-fill{position:absolute;left:0;top:0;bottom:0;background:color-mix(in srgb,var(--fw-t2) 14%,transparent)}
.mus-row.is-failed .mus-lane{background:repeating-linear-gradient(135deg,transparent 0 6px,color-mix(in srgb,var(--fw-err) 18%,transparent) 6px 8px)}
.mus-note{position:absolute;height:.125rem;background:var(--fw-t2)}
.mus-chord{position:absolute;top:0;color:var(--fw-t3);font-size:var(--fw-fs-meta,.6875rem);white-space:nowrap}
.mus-tp{display:flex;align-items:center;gap:12px;height:var(--fw-bar-h,2.25rem);padding:0 12px;border-top:1px solid var(--fw-line-2);flex:none;min-width:0}
.mus-tp-clock{font-size:var(--fw-fs-title,.875rem);font-weight:600;color:var(--fw-t1);min-width:9ch}
.mus-tp-btns{display:flex;gap:4px;margin:0 auto}
.mus-tp-total{color:var(--fw-t2);white-space:nowrap}
.mus-model{display:flex;align-items:center;gap:4px;padding:8px 12px}
.mus-model>.fw-select{flex:1 1 auto;min-width:0}
.mus-files{padding:0 12px 8px;color:var(--fw-t3)}
.mus-files .aud-why{color:var(--fw-warn)}
.mus-ta{width:100%;box-sizing:border-box;resize:vertical;min-height:var(--aud-ta)}
.mus-sec-b{display:grid;gap:8px;padding:0 12px 12px}
/* w18-acre2: inside a section body the rows sit on the body's own 12 px inset (board 2d), not a second one. */
.fw-sec-b>.mus-sec-b,.fw-sec-b>.aud-sec-b{padding:0}
.mus-prow{display:grid;grid-template-columns:68px minmax(0,1fr);gap:8px;align-items:center;min-width:0}
.mus-prow>label{color:var(--fw-t3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mus-prow .fw-select,.mus-prow .aud-in{width:100%;box-sizing:border-box;min-width:0}
.mus-kv{display:grid;grid-template-columns:68px minmax(0,1fr);gap:4px 8px;padding:0 12px 12px}
.mus-kv>span:nth-child(odd){color:var(--fw-t3)}
.mus-gen{display:flex;gap:6px}
.mus-gen>.fw-btn-primary{flex:1 1 auto}
.mus-gen>.fw-select{width:64px;flex:none;height:var(--fw-bar-h,2.25rem)}
`;

